mapper.insert:
insert into issue_provider_execution_results() values(
 #{value.tenantId},#{value.resultId},#{value.adapterActionId},#{value.taskId},#{value.adapterActionType},#{value.attemptNo},#{value.observationKind},#{value.provider},#{value.operation},#{value.disposition},#{value.providerOutcomeCertainty},#{value.providerStatusCode},#{value.retryable},#{value.failureCode},#{value.providerHealthImpact},#{value.externalProjectId},#{value.externalIssueId},#{value.externalIssueKey},#{value.externalIssueUrl},#{value.externalStatus},#{value.responseRef},#{value.responseFingerprint},#{value.idempotencyKey},#{value.operationFingerprint},#{value.correlationId},#{value.a2aRequestId},#{value.sourceSystemId},#{value.connectionId},#{value.projectMappingId},#{value.technicalPrincipalId},#{value.credentialId},#{value.credentialVersion},#{value.errorMessage},#{value.executedAt},#{value.projectionStatus},#{value.projectionAttemptCount},#{value.projectionMaxAttempts},#{value.nextProjectionAttemptAt},#{value.lastProjectionError},#{value.projectedAt},coalesce(#{value.createdAt},now()),coalesce(#{value.updatedAt},now())
) on conflict(adapter_action_id,attempt_no,observation_kind) do nothing

mapper.select:
select  from issue_provider_execution_results
 where projection_status in ('PENDING','RETRY_WAITING') and (next_projection_attempt_at is null or next_projection_attempt_at <=#{now})
 order by executed_at asc limit #{limit}
